describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow("upToGrams must be a positive integer");
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow("costCents must be a non-negative integer");
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents(emptyLines, 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const noWeightLine: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(noWeightLine, 5000)).toBe(0);
    });

    it("selects first bracket when weight <= lowest upToGrams", () => {
      expect(calc.computeShippingCents([mkLine("a", 250, 2)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      expect(calc.computeShippingCents([mkLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds lower boundary", () => {
      expect(calc.computeShippingCents([mkLine("a", 501, 1)], 5000)).toBe(700);
    });

    it("selects highest bracket at its boundary", () => {
      expect(calc.computeShippingCents([mkLine("a", 5000, 1)], 5000)).toBe(
        1200,
      );
    });

    it("uses heaviest bracket cost as overflow default", () => {
      expect(calc.computeShippingCents([mkLine("a", 6000, 1)], 5000)).toBe(
        1200,
      );
    });

    it("uses explicit overflowCostCents when provided", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      expect(
        calcWithOverflow.computeShippingCents([mkLine("a", 3000, 1)], 5000),
      ).toBe(1500);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(unordered.computeShippingCents([mkLine("a", 400, 1)], 5000)).toBe(
        300,
      );
      expect(
        unordered.computeShippingCents([mkLine("a", 1000, 1)], 5000),
      ).toBe(700);
    });

    it("sums weight across multiple lines", () => {
      // 300g * 2 + 200g * 3 = 1200g → falls in the 2000g bracket
      const lines = [mkLine("a", 300, 2), mkLine("b", 200, 3)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(700);
    });
  });
});

