describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "p1", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 200, weightGrams: 500 }, quantity: 1 },
  ];

  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[0].quantity).toBe(2);
    expect(result[1].product.unitPriceCents).toBe(250);
    expect(result[1].product.weightGrams).toBe(500); // preserves other fields
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p2");
  });

  it("does not mutate original lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(lines[0].product.unitPriceCents).toBe(100); // unchanged
    expect(result[0].product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("invalid price");
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("network error");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].product.id).toBe("a");
    expect(snap[0].quantity).toBe(3);
  });

  it("merges quantities when adding the same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0].quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 7);
    expect(cart.itemCount).toBe(7);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("nonexistent", 5)).toThrow(
      "not in the cart",
    );
  });

  it("clear removes all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns deep copy", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 1;
    // Original cart unaffected
    expect(cart.snapshot()[0].quantity).toBe(2);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

describe("Cart – totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents × quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(350),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 5); // subtotal = 5000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(500);
    // Tax computed on discounted subtotal
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
    expect(totals.taxCents).toBe(350);
    // Shipping computed with discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      4500,
    );
    expect(totals.shippingCents).toBe(200);
    // Total = discountedSubtotal + tax + shipping
    expect(totals.totalCents).toBe(4500 + 350 + 200);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount exceeds subtotal
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
