    const cart = new Cart();
    cart.add(productA, 2);
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 100,
      }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider to compute tax", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US-CA" });
    cart.add(productA, 1); // subtotal 1000, no discount, 10% tax = 100

    const result = await cart.checkout({ asyncTaxProvider: taxProvider });

    expect(taxProvider.getRate).toHaveBeenCalledWith("US-CA");
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.totalCents).toBe(1100);
  });

  it("composes discount + async tax + shipping correctly", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "FR",
    });
    cart.add(productA, 3); // subtotal 3000, discount 200, discounted 2800, tax 10% of 2800 = 280

    const result = await cart.checkout({ asyncTaxProvider: taxProvider });

    expect(result.totals.subtotalCents).toBe(3000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(280);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2800 + 280 + 500);
  });

  it("propagates async tax provider rejection", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(
      cart.checkout({ asyncTaxProvider: taxProvider }),
    ).rejects.toThrow("tax service down");
  });

  it("checks inventory for multiple products and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);

    const checker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("does not mutate internal cart state via checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(9999),
    };
    await cart.checkout({ priceFetcher: fetcher });

    // Internal cart should still have original price
    expect(cart.totals().subtotalCents).toBe(2000);
  });

  it("uses sync tax calculator when no asyncTaxProvider is given", async () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(50);
    expect(tax.computeTaxCents).toHaveBeenCalled();
